{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C56", "C48", "C58", "C49", "C38", "C44", "C36", "C08", "C05", "C10", "C13"],
  "contradictory_card_ids": ["C50"],
  "prediction_basis_card_ids": ["C56", "C38", "C44", "C36", "C08"],
  "claims": [
    {
      "claim": "Lisinopril, the closest structural analog sharing the query lysine side chain and diacid ACE-inhibitor scaffold, has low predicted passive diffusion but significantly higher in vivo human jejunal effective permeability because of carrier-mediated uptake via hPepT1, directly supporting carrier-mediated absorption for the query.",
      "card_ids": ["C56"]
    },
    {
      "claim": "Cephalexin, a zwitterionic peptide-like drug with an aromatic phenylglycine side chain, is a confirmed Pept1 substrate, showing that peptide-like zwitterions with aromatic groups are transported by the intestinal peptide transporter.",
      "card_ids": ["C58"]
    },
    {
      "claim": "Bestatin, a peptide-like drug, is transported by PEPT1 in PEPT1-expressing Xenopus oocytes, confirming that PEPT1 handles peptide-mimetic drugs beyond classical dipeptides.",
      "card_ids": ["C48"]
    },
    {
      "claim": "Enalapril shows higher apical-to-basolateral permeability in hiPSC-derived intestinal epithelial layers than in Caco-2 monolayers, indicating that Caco-2 can underestimate intestinal permeability for ACE inhibitors.",
      "card_ids": ["C49"]
    },
    {
      "claim": "Enalaprilat has low human jejunal effective permeability, but it lacks the lysine primary amine that is the key PEPT1 recognition element present in the query, so this low-permeability record does not transfer to the query.",
      "card_ids": ["C50"]
    },
    {
      "claim": "Human ampicillin records, the closest transferable zwitterionic amino-acid context, report oral F of 29% in fasted female subjects and 28-54% in cirrhotic patients, all above the 20% threshold.",
      "card_ids": ["C08", "C05", "C10", "C13"]
    },
    {
      "claim": "Lisinopril and benazepril, which shares the benzazepinone N-acetic acid ring with the query, were highly soluble and did not precipitate in intrinsic solubility determinations, supporting adequate dissolution.",
      "card_ids": ["C44", "C36"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C56", "C48", "C58", "C49"]
    },
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C50"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "No direct PEPT1 or efflux assay on the query itself is supplied; C56 names lisinopril, not the query.",
    "The query prandial state and disease condition are unspecified.",
    "First-pass hepatic extraction and systemic clearance are not addressed.",
    "The query PEPT1 recognition is inferred from the lysine side chain, not measured.",
    "The extreme logD of -8.18 remains a physicochemical prior, not affirmative endpoint evidence for F below 20%."
  ],
  "decision_summary": "L5 gut-wall and intestinal-transport evidence strengthens the high prediction. Lisinopril, the closest analog sharing the lysine side chain and diacid scaffold, is a confirmed hPepT1 substrate with carrier-mediated jejunal uptake (C56). Peptide-like zwitterionic drugs are PEPT1 substrates (C58, C48). The only low-permeability diacid record, enalaprilat (C50), lacks the lysine primary amine and does not transfer. No affirmative threshold-relevant evidence supports F below 20%."
}

